def norm(b: bytes) -> str:
    return b.decode("utf-8-sig", errors="replace").replace("\r\n", "\n")


def main():
    if not (ROOT / "core" / "policy.py").exists() or not (ROOT / "agent" / "runner.py").exists():
        sys.exit("HATA: Bu betigi JARVIS proje klasorune (core/ ve agent/ klasorlerinin yanina) koyun.")
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    bdir = ROOT / f"fix_backup_{stamp}"
    plan, skipped = [], []
    for item in PAYLOAD:
        rel, target = item["path"], ROOT / item["path"]
        new_text = zlib.decompress(base64.b64decode(item["data"])).decode("utf-8")
        if target.exists():
            cur = norm(target.read_bytes())
            if cur == new_text:
                continue
            if item["sha_orig"] and hashlib.sha256(cur.encode()).hexdigest() != item["sha_orig"] and not FORCE:
                skipped.append(rel)
                continue
        plan.append((rel, target, new_text, target.exists()))
    print(f"Degisecek/eklenecek dosya: {len(plan)}  |  atlanan (sonradan degistirilmis): {len(skipped)}")
    for rel, _, _, existed in plan:
        print(("  ~ " if existed else "  + ") + rel)
    for rel in skipped:
        print("  ! ATLANDI (dosya benim yamaladigim surumden farkli, --force ile zorlayin): " + rel)
    if DRY or not plan:
        print("Dry-run / yapilacak is yok; hicbir sey yazilmadi.")
        return
    written = []
    try:
        for rel, target, text, existed in plan:
            if existed:
                dest = bdir / rel
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(target, dest)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text, encoding="utf-8", newline="\n")
            written.append((rel, target, existed))
        for rel, target, _ in written:
            if rel.endswith(".py"):
                py_compile.compile(str(target), doraise=True)
    except Exception as exc:
        print(f"HATA: {exc}\nGeri aliniyor...")
        for rel, target, existed in written:
            if existed and (bdir / rel).exists():
                shutil.copy2(bdir / rel, target)
            elif target.exists():
                target.unlink()
        sys.exit("Degisiklikler geri alindi.")
    print(f"\nTamam. Yedek: {bdir.name}/")
    print("Siradaki adimlar:\n  1) python -m pytest -q\n  2) python storage_cleanup.py        (rapor)\n  3) python storage_cleanup.py --apply  (hafiza/gorev temizligi)")


if __name__ == "__main__":
    main()
